    capacity = read(instance, "capacity", read(instance, "vehicle_capacity", None))
    depot = read(instance, "depot", None)
    depot_id = read(instance, "depot_id", 0)

    coords = read(instance, "coords", read(instance, "coordinates", read(instance, "points", None)))
    demands = read(instance, "demands", read(instance, "demand", None))
    customers = read(instance, "customers", None)

    coord_map = {}
    if isinstance(coords, dict):
        for k in coords:
            pt = as_point(coords[k])
            if pt is not None:
                coord_map[k] = pt
    elif isinstance(coords, (list, tuple)):
        for i in range(len(coords)):
            pt = as_point(coords[i])
            if pt is not None:
                coord_map[i] = pt

    demand_map = {}
    if isinstance(demands, dict):
        for k in demands:
            try:
                demand_map[k] = float(demands[k])
            except Exception:
                demand_map[k] = 0.0
    elif isinstance(demands, (list, tuple)):
        for i in range(len(demands)):
            try:
                demand_map[i] = float(demands[i])
            except Exception:
                demand_map[i] = 0.0

    def dmd(c):
        if c in demand_map:
            return demand_map[c]
        if isinstance(c, int) and (c + 1) in demand_map:
            return demand_map[c + 1]
        return 0.0

    def pt(c):
        if c in coord_map:
            return coord_map[c]
        if isinstance(c, int) and (c + 1) in coord_map:
            return coord_map[c + 1]
        return None

    if customers is None:
        n = read(instance, "n", read(instance, "num_customers", None))
        if n is None and isinstance(demands, (list, tuple)):
            n = len(demands) - 1
        if n is None and isinstance(coords, (list, tuple)):
            n = len(coords) - 1
        if n is None:
            n = 0
        customers = list(range(1, n + 1))
    else:
        customers = list(customers)

    depot_point = None
    if isinstance(depot, (list, tuple)):
        depot_point = as_point(depot)
    elif depot in coord_map:
        depot_point = coord_map[depot]
    elif depot_id in coord_map:
        depot_point = coord_map[depot_id]
    elif 0 in coord_map:
        depot_point = coord_map[0]
    elif 1 in coord_map and depot_id == 0:
        depot_point = coord_map[1]

    custs = []
    for c in customers:
        if c != depot and c != depot_id:
            custs.append(c)

    total_demand = 0.0
    for c in custs:
        total_demand += dmd(c)
    if capacity is None:
        capacity = total_demand if total_demand > 0 else 10**18

    has_coords = depot_point is not None
    ordered = []
    if has_coords:
        items = []
        for c in custs:
            p = pt(c)
            if p is None:
                has_coords = False
                break
            dx = p[0] - depot_point[0]
            dy = p[1] - depot_point[1]
            if dx == 0 and dy == 0:
                ang = -10**9
            else:
                ang = 0.0
                if dy >= 0:
                    ang = dx / (abs(dy) + abs(dx) + 1e-12) + (0.0 if dx >= 0 else 2.0)
                else:
                    ang = 4.0 + dx / (abs(dy) + abs(dx) + 1e-12)
            items.append((ang, dx * dx + dy * dy, c))
        if has_coords:
            items.sort(key=lambda t: (t[0], t[1], t[2]))
            ordered = [t[2] for t in items]
    if not has_coords:
        ordered = sorted(custs)

    routes = []
    cur = []
    load = 0.0
    for c in ordered:
        dem = dmd(c)
        if dem > capacity and cur:
            routes.append(cur)
            cur = []
            load = 0.0
        if not cur or load + dem <= capacity:
            cur.append(c)
            load += dem
        else:
            routes.append(cur)
            cur = [c]
            load = dem
    if cur:
        routes.append(cur)

    def route_load(r):
        s = 0.0
        for c in r:
            s += dmd(c)
        return s

    changed = True
    rounds = 0
    while changed and rounds < 4:
        rounds += 1
        changed = False
        loads = [route_load(r) for r in routes]
        for i in range(len(routes)):
            for j in range(len(routes)):
                if i == j or not routes[i]:
                    continue
                if loads[i] <= loads[j]:
                    continue
                best_k = -1
                best_score = None
                for k in range(len(routes[i])):
                    c = routes[i][k]
                    dem = dmd(c)
                    if loads[j] + dem > capacity:
                        continue
                    score = dem
                    if has_coords:
                        p = pt(c)
                        if p is not None:
                            score += dist(p, depot_point)
                    if best_score is None or score > best_score or (score == best_score and c < routes[i][best_k]):
                        best_score = score
                        best_k = k
                if best_k >= 0:
                    c = routes[i].pop(best_k)
                    routes[j].append(c)
                    loads[i] -= dmd(c)
                    loads[j] += dmd(c)
                    changed = True

    def route_cost(r):
        if not has_coords or not r:
            return 0.0
        total = 0.0
        prev = depot_point
        for c in r:
            p = pt(c)
            if p is None:
                return 0.0
            total += dist(prev, p)
            prev = p
        total += dist(prev, depot_point)
        return total

    def improve(r):
        if not has_coords or len(r) < 3:
            return r
        best = r[:]
        best_cost = route_cost(best)
        improved = True
        tries = 0
        while improved and tries < 8:
            tries += 1
            improved = False
            n = len(best)
            for i in range(n - 1):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    cst = route_cost(cand)
                    if cst + 1e-12 < best_cost:
                        best = cand
                        best_cost = cst
                        improved = True
        return best

    for i in range(len(routes)):
        routes[i] = improve(routes[i])

    final_routes = []
    for r in routes:
        cur = []
        load = 0.0
        for c in r:
            dem = dmd(c)
            if cur and load + dem > capacity:
                final_routes.append(cur)
                cur = [c]
                load = dem
            else:
                cur.append(c)
                load += dem
        if cur:
            final_routes.append(cur)

    return final_routes
